<#
.SYNOPSIS
    MNCH Assessment Mobile App - React scaffold script
.DESCRIPTION
    Creates the full src/ folder structure and writes all source files.
    Run from the root of your React project (where package.json lives).
    Usage:  PowerShell -ExecutionPolicy Bypass -File .\scaffold-mnch-app.ps1
#>

param(
    [string]$Root = (Get-Location).Path
)

$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "  MNCH Assessment App - Scaffold" -ForegroundColor Cyan
Write-Host "  Target: $Root" -ForegroundColor Gray
Write-Host ""

function Write-SourceFile {
    param([string]$RelativePath, [string]$Base64Content)
    $fullPath = Join-Path $Root $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        Write-Host "  [DIR]  $(($dir).Replace($Root, '.'))" -ForegroundColor DarkGray
    }
    $bytes = [Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  [OK]   $RelativePath" -ForegroundColor Green
}

Write-Host "Creating directories..." -ForegroundColor Yellow
@("src","src\screens","src\components","src\services") | ForEach-Object {
    $p = Join-Path $Root $_
    if (-not (Test-Path $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null }
}

Write-Host ""
Write-Host "Writing source files..." -ForegroundColor Yellow

$b64_src_App_jsx = ""
Write-SourceFile -RelativePath "src\App.jsx" -Base64Content $b64_src_App_jsx

$b64_src_constants_js = ""
Write-SourceFile -RelativePath "src\constants.js" -Base64Content $b64_src_constants_js

$b64_src_services_api_service_js = ""
Write-SourceFile -RelativePath "src\services\api.service.js" -Base64Content $b64_src_services_api_service_js

$b64_src_components_shared_components_jsx = ""
Write-SourceFile -RelativePath "src\components\shared-components.jsx" -Base64Content $b64_src_components_shared_components_jsx

$b64_src_components_question_inputs_jsx = ""
Write-SourceFile -RelativePath "src\components\question-inputs.jsx" -Base64Content $b64_src_components_question_inputs_jsx

$b64_src_screens_screen_login_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-login.jsx" -Base64Content $b64_src_screens_screen_login_jsx

$b64_src_screens_screen_dashboard_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-dashboard.jsx" -Base64Content $b64_src_screens_screen_dashboard_jsx

$b64_src_screens_screen_assessments_list_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-assessments-list.jsx" -Base64Content $b64_src_screens_screen_assessments_list_jsx

$b64_src_screens_screen_assessment_detail_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-assessment-detail.jsx" -Base64Content $b64_src_screens_screen_assessment_detail_jsx

$b64_src_screens_screen_assessment_form_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-assessment-form.jsx" -Base64Content $b64_src_screens_screen_assessment_form_jsx

$b64_src_screens_screen_reports_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-reports.jsx" -Base64Content $b64_src_screens_screen_reports_jsx

$b64_src_screens_screen_profile_jsx = ""
Write-SourceFile -RelativePath "src\screens\screen-profile.jsx" -Base64Content $b64_src_screens_screen_profile_jsx


Write-Host ""
Write-Host "  Scaffold complete!" -ForegroundColor Cyan
Write-Host ""
Write-Host "  src/" -ForegroundColor White
Write-Host "  +-- App.jsx" -ForegroundColor White
Write-Host "  +-- constants.js" -ForegroundColor White
Write-Host "  +-- services/" -ForegroundColor White
Write-Host "  |   +-- api.service.js" -ForegroundColor White
Write-Host "  +-- components/" -ForegroundColor White
Write-Host "  |   +-- shared-components.jsx" -ForegroundColor White
Write-Host "  |   +-- question-inputs.jsx" -ForegroundColor White
Write-Host "  +-- screens/" -ForegroundColor White
Write-Host "      +-- screen-login.jsx" -ForegroundColor White
Write-Host "      +-- screen-dashboard.jsx" -ForegroundColor White
Write-Host "      +-- screen-assessments-list.jsx" -ForegroundColor White
Write-Host "      +-- screen-assessment-detail.jsx" -ForegroundColor White
Write-Host "      +-- screen-assessment-form.jsx" -ForegroundColor White
Write-Host "      +-- screen-reports.jsx" -ForegroundColor White
Write-Host "      +-- screen-profile.jsx" -ForegroundColor White
Write-Host ""
Write-Host "  Next steps:" -ForegroundColor Yellow
Write-Host "    1. Set REACT_APP_API_URL in your .env file" -ForegroundColor White
Write-Host "       REACT_APP_API_URL=https://mnchkenyamentorship.org/api/v1" -ForegroundColor DarkGray
Write-Host "    2. Uncomment api.* calls in each screen file" -ForegroundColor White
Write-Host "    3. Uncomment loadData() in src\App.jsx" -ForegroundColor White
Write-Host ""